package br.com.casaclara.domain

/** Teste rápido de conhecimentos da vida independente. Cada pergunta aponta para um guia da biblioteca. */
object Quiz {
    data class Q(val id: String, val text: String, val options: List<String>, val correct: Int, val explain: String, val guide: String)

    val ALL = listOf(
        Q("q1", "Um banco liga pedindo o código que chegou por SMS para \"proteger sua conta\". O que fazer?", listOf("Passar o código rapidamente", "Desligar e ligar para o número oficial do banco", "Passar só metade do código", "Pedir para ligarem mais tarde"), 1, "Banco nunca pede código, senha ou transferência. Desligue e ligue você para o número do verso do cartão.", "golpe-falsa-central"),
        Q("q2", "Qual é o prazo de arrependimento para compras pela internet?", listOf("3 dias", "7 dias", "15 dias", "30 dias"), 1, "São 7 dias corridos a partir do recebimento, com devolução integral do valor, incluindo frete.", "direito-arrependimento"),
        Q("q3", "Qual é a garantia legal de um produto durável, como uma geladeira?", listOf("30 dias", "90 dias", "6 meses", "Só a do fabricante"), 1, "Produtos duráveis têm 90 dias de garantia legal, somados à garantia do fabricante.", "garantia-legal"),
        Q("q4", "Sentiu cheiro de gás em casa. O que NÃO fazer?", listOf("Abrir as janelas", "Fechar o registro", "Acender a luz para enxergar melhor", "Sair e ligar para os bombeiros"), 2, "Ligar interruptores pode gerar faísca. Ventile, feche o registro, saia e ligue 193 de fora.", "vazamento-gas"),
        Q("q5", "Qual número chamar numa emergência de saúde, como alguém desmaiado?", listOf("190", "192", "193", "199"), 1, "192 é o SAMU. 193 são os Bombeiros, 190 a Polícia e 199 a Defesa Civil.", "quando-upa"),
        Q("q6", "Em 2026, quem ganha até quanto por mês fica isento do Imposto de Renda na fonte?", listOf("R$ 2.428,80", "R$ 3.000", "R$ 5.000", "R$ 7.350"), 2, "A Lei 15.270/2025 zerou o IR na fonte para rendimentos de até R$ 5.000 por mês.", "salario-liquido-guia"),
        Q("q7", "Quanto a empresa deposita de FGTS por mês para quem tem carteira assinada?", listOf("2% do salário", "8% do salário", "10% do salário", "Nada, é descontado do salário"), 1, "São 8% do salário, pagos pela empresa, sem descontar de você.", "fgts"),
        Q("q8", "Nas férias, além do salário, você recebe:", listOf("Nada a mais", "Um terço a mais", "Metade a mais", "Um salário extra"), 1, "As férias são pagas com um adicional de um terço do valor.", "ferias-direitos"),
        Q("q9", "Qual é a regra mais usada para o aluguel caber no bolso?", listOf("Até 10% da renda", "Até 30% da renda", "Até 50% da renda", "Até 70% da renda"), 1, "A referência comum é a moradia ficar em até cerca de 30% da renda, para sobrar para o resto.", "custo-real"),
        Q("q10", "Para que serve a reserva de emergência?", listOf("Comprar algo em promoção", "Imprevistos, como perder o emprego ou um conserto urgente", "Viajar nas férias", "Investir em ações"), 1, "É dinheiro guardado só para imprevistos. Muitas pessoas miram de 3 a 6 meses de custo de vida.", "reserva-emergencia"),
        Q("q11", "Recebeu um \"oi, troquei de número\" de um parente pedindo Pix. O melhor é:", listOf("Mandar logo, é família", "Ligar para o número antigo da pessoa antes", "Mandar metade", "Pedir o comprovante depois"), 1, "Confirme por outro caminho, de preferência ligando para o número que você já tinha.", "golpe-falso-parente"),
        Q("q12", "Onde é melhor guardar remédios?", listOf("No banheiro", "Em local seco e fresco, longe do banheiro", "Em cima da geladeira", "No carro"), 1, "O vapor do banheiro e o calor estragam os remédios.", "remedios-casa"),
        Q("q13", "Para uma consulta de rotina pelo SUS, onde começar?", listOf("Pronto-socorro", "UBS (posto de saúde)", "SAMU", "Hospital particular"), 1, "A UBS é a porta de entrada: consulta, vacina e encaminhamentos.", "sus-como-usar"),
        Q("q14", "Na primeira parcela do 13º, quais descontos há?", listOf("INSS e IR", "Só INSS", "Nenhum", "Só IR"), 2, "A primeira parcela vem sem descontos; INSS e IR saem da segunda.", "decimo-terceiro"),
        Q("q15", "Queimadura leve na cozinha: qual o primeiro cuidado?", listOf("Pasta de dente", "Manteiga", "Água corrente fria por cerca de 20 minutos", "Gelo direto na pele"), 2, "Água corrente fria (não gelada). Nada de receitas caseiras.", "queimadura-leve"),
        Q("q16", "Um cano estourou em casa. O que fazer primeiro?", listOf("Ligar para um amigo", "Fechar o registro geral de água", "Colocar balde e esperar", "Postar nas redes"), 1, "Fechar o registro geral para o vazamento. Depois, proteger o que for elétrico e chamar o encanador.", "cano-estourado"),
        Q("q17", "Antes de confirmar um Pix, o mais importante é conferir:", listOf("A cor do app", "O nome de quem vai receber", "A hora", "Se tem internet boa"), 1, "O nome do recebedor mostra para quem o dinheiro vai de verdade.", "golpe-pix"),
        Q("q18", "Qual destas é uma boa prática de senha?", listOf("Data de nascimento", "A mesma senha em tudo", "Frase longa e diferente para e-mail e banco", "123456 com um símbolo"), 2, "Frases longas e senhas diferentes para contas importantes protegem muito mais.", "senhas-fortes"),
        Q("q19", "No contrato de aluguel, quantas garantias podem ser exigidas ao mesmo tempo?", listOf("Uma", "Duas", "Três", "Quantas o dono quiser"), 0, "A Lei do Inquilinato permite só uma modalidade de garantia por contrato.", "direitos-inquilino"),
        Q("q20", "O vale-transporte pode descontar até quanto do salário-base?", listOf("2%", "6%", "10%", "15%"), 1, "O desconto máximo é de 6% do salário-base (ou o custo das passagens, se for menor).", "bilhete-integracao"),
        Q("q21", "Qual o jeito mais seguro de pagar uma compra on-line numa loja desconhecida?", listOf("Pix", "Depósito em conta de pessoa física", "Cartão de crédito ou cartão virtual", "Boleto enviado por WhatsApp"), 2, "Com cartão é mais fácil contestar se algo der errado.", "compras-online-seguras"),
        Q("q22", "Conta de água subiu do nada. Um bom teste é:", listOf("Trocar o chuveiro", "Fechar tudo e ver se o hidrômetro continua andando", "Pagar e esquecer", "Desligar a geladeira"), 1, "Se o hidrômetro anda com tudo fechado, há vazamento.", "conta-agua-entender"),
        Q("q23", "O que é o CadÚnico?", listOf("Um cartão de crédito", "O cadastro para programas sociais e tarifas sociais", "Um documento de identidade", "O cadastro do imposto de renda"), 1, "É a porta de entrada para benefícios como tarifa social de energia.", "cadunico"),
        Q("q24", "Vaga de emprego que pede pagamento para uniforme ou curso é:", listOf("Normal", "Sinal de golpe", "Obrigatória por lei", "Comum em grandes empresas"), 1, "Empresa séria não cobra para você trabalhar.", "golpe-vaga-emprego"),
        Q("q25", "Ao alugar, o que é essencial fazer na entrega das chaves?", listOf("Nada", "Vistoria com fotos de tudo", "Pintar a casa", "Trocar a fechadura sem avisar"), 1, "Fotos e vistoria protegem você na hora de devolver o imóvel.", "registrar-chaves"),
        Q("q26", "Para economizar luz, qual aparelho costuma pesar mais?", listOf("Carregador de celular", "Chuveiro elétrico", "Lâmpada de LED", "Rádio"), 1, "Chuveiro elétrico é um dos grandes vilões da conta.", "conta-luz-entender"),
        Q("q27", "Picada de escorpião. O que fazer?", listOf("Fazer torniquete", "Cortar o local", "Lavar e procurar atendimento imediato", "Esperar passar"), 2, "Lave com água e sabão e procure atendimento ou ligue 192.", "animais-peconhentos"),
        Q("q28", "Chegou em casa e a porta está arrombada. O que fazer?", listOf("Entrar para ver o que sumiu", "Não entrar, afastar-se e ligar 190", "Chamar o vizinho para entrar junto", "Trocar a fechadura na hora"), 1, "A pessoa pode ainda estar lá. Sua segurança vem primeiro.", "invasao-casa"),
        Q("q29", "Qual destes é o melhor destino para dinheiro com juros altos de dívida?", listOf("Deixar a dívida e investir", "Quitar ou negociar a dívida com juros mais altos primeiro", "Fazer outra dívida para pagar", "Ignorar"), 1, "Dívidas como cartão rotativo e cheque especial crescem muito rápido.", "juros-divida"),
        Q("q30", "A melhor forma de não esquecer contas é:", listOf("Confiar na memória", "Lembretes e débito automático das contas fixas", "Pagar só quando cortarem", "Pagar tudo no fim do ano"), 1, "Lembretes no app e débito automático evitam juros e multas.", "evitar-atrasos"),
        Q("q31", "Para fazer amizades numa cidade nova, o que costuma funcionar melhor?", listOf("Esperar alguém chamar", "Atividades com encontros que se repetem toda semana", "Só redes sociais", "Mudar de cidade de novo"), 1, "A repetição cria intimidade: esporte, curso, voluntariado, grupo.", "fazer-amizades"),
        Q("q32", "Onde emitir segunda via de documentos com segurança?", listOf("Sites que aparecem no anúncio", "Sites .gov.br e apps oficiais", "Grupos de WhatsApp", "Qualquer despachante on-line"), 1, "Documentos oficiais se emitem em canais oficiais, geralmente .gov.br.", "documentos-essenciais"),
    )

    fun draw(n: Int, seed: Long): List<Q> = ALL.shuffled(java.util.Random(seed)).take(n)
    fun score(questions: List<Q>, answers: Map<String, Int>): Int = questions.count { answers[it.id] == it.correct }
}
